const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const slugify=s=>String(s||'').toLowerCase().trim().replace(/[ё]/g,'e').replace(/[^a-zа-я0-9]+/gi,'-').replace(/^-+|-+$/g,'')||'new-page';
const notice=(text,type='ok')=>{const n=$('#notice');n.textContent=text;n.className='notice'+(type==='error'?' error':'');n.hidden=false;clearTimeout(notice.t);notice.t=setTimeout(()=>n.hidden=true,6000)};
function safeInternalHref(value,fallback=BASE){try{const raw=String(value||'').trim();if(raw.startsWith('#'))return raw;const u=new URL(raw,location.origin);if(u.origin!==location.origin||!u.pathname.startsWith(BASE))return fallback;return u.pathname+u.search+u.hash}catch{return fallback}}
function safeContentHref(value,{image=false}={}){const raw=String(value||'').trim();if(!raw)return '';if(raw.startsWith('#'))return raw;if(image&&/^data:image\/(?:png|jpe?g|gif|webp);base64,/i.test(raw))return raw;try{const u=new URL(raw,location.origin);if(u.origin===location.origin&&u.pathname.startsWith(BASE))return u.pathname+u.search+u.hash;if(image)return '';if(u.protocol==='https:')return u.href}catch{}return ''}
function sanitizeEditorBody(raw){
 const doc=new DOMParser().parseFromString('<div id="tl-sanitize-root">'+String(raw||'')+'</div>','text/html');
 const root=doc.getElementById('tl-sanitize-root');let changed=false;
 const allowedTags=new Set(['A','ARTICLE','ASIDE','BLOCKQUOTE','BR','CODE','DD','DETAILS','DIV','DL','DT','EM','FIGCAPTION','FIGURE','H2','H3','H4','H5','H6','HEADER','HR','I','IMG','LI','MARK','NAV','OL','P','PRE','SECTION','SMALL','SPAN','STRONG','SUMMARY','TABLE','TBODY','TD','TFOOT','TH','THEAD','TIME','TR','U','UL','B','LABEL','INPUT']);
 const allowedData=new Set(['data-full-src','data-core-depth','data-track','data-search','data-card-link','data-level','data-topic','data-source','data-problem']);
 root.querySelectorAll('script,style,iframe,object,embed,base,meta,link,form,svg,math,template,video,audio,source,track,canvas').forEach(el=>{el.remove();changed=true});
 [...root.querySelectorAll('*')].forEach(el=>{
   if(!allowedTags.has(el.tagName)){el.replaceWith(...el.childNodes);changed=true;return}
   [...el.attributes].forEach(a=>{
     const n=a.name.toLowerCase();
     const ok=n==='class'||n==='id'||n==='href'||n==='src'||n==='alt'||n==='width'||n==='height'||n==='loading'||n==='decoding'||n==='referrerpolicy'||n==='rel'||n==='target'||n==='title'||n==='type'||n==='checked'||n==='disabled'||n==='hidden'||n==='role'||n==='tabindex'||n==='datetime'||n==='colspan'||n==='rowspan'||n==='scope'||n.startsWith('aria-')||allowedData.has(n);
     if(n.startsWith('on')||n==='style'||n==='srcdoc'||n==='formaction'||n==='xlink:href'||n==='name'||!ok){el.removeAttribute(a.name);changed=true}
   });
   if(el.tagName==='A'){
     const href=safeContentHref(el.getAttribute('href'));if(href)el.setAttribute('href',href);else if(el.hasAttribute('href')){el.removeAttribute('href');changed=true}
     const target=el.getAttribute('target');if(target&&target!=='_blank'){el.removeAttribute('target');changed=true}
     if(el.getAttribute('target')==='_blank'){const rel=new Set((el.getAttribute('rel')||'').split(/\s+/).filter(Boolean));rel.add('noopener');rel.add('noreferrer');el.setAttribute('rel',[...rel].join(' '))}
   }
   if(el.tagName==='IMG'){
     const src=safeContentHref(el.getAttribute('src'),{image:true});if(src)el.setAttribute('src',src);else{el.removeAttribute('src');changed=true}
     const full=el.getAttribute('data-full-src');const safeFull=safeContentHref(full,{image:true});if(full&&safeFull)el.setAttribute('data-full-src',safeFull);else if(full){el.removeAttribute('data-full-src');changed=true}
   }
   if(el.hasAttribute('data-card-link')){const card=safeInternalHref(el.getAttribute('data-card-link'),'');if(card)el.setAttribute('data-card-link',card);else{el.removeAttribute('data-card-link');changed=true}}
   if(el.tagName==='INPUT'){
     const type=(el.getAttribute('type')||'checkbox').toLowerCase();
     if(type!=='checkbox'){el.remove();changed=true}else{el.setAttribute('type','checkbox');el.removeAttribute('id');el.setAttribute('tabindex','-1')}
   }
 });
 return {html:root.innerHTML.trim(),changed}
}

const REPO_SESSION_KEY='trafficlab-admin-repo';
function loadSession(){try{const x=JSON.parse(sessionStorage.getItem(REPO_SESSION_KEY)||'{}');state.repo.owner=x.owner||state.repo.owner;state.repo.repo=x.repo||state.repo.repo;state.repo.branch=x.branch||state.repo.branch;state.repo.token=typeof x.token==='string'?x.token:''}catch{state.repo.token=''}['owner','repo','branch'].forEach(k=>{const el=$('#repo'+k[0].toUpperCase()+k.slice(1));if(el)el.value=state.repo[k]||''});const token=$('#repoToken');token.value='';token.placeholder=state.repo.token?'Токен сохранён до закрытия вкладки':'github_pat_...'}
function saveSession(){const entered=$('#repoToken').value.trim();state.repo={owner:$('#repoOwner').value.trim(),repo:$('#repoName').value.trim(),branch:$('#repoBranch').value.trim()||'main',token:entered||state.repo.token};sessionStorage.setItem(REPO_SESSION_KEY,JSON.stringify(state.repo));$('#repoToken').value='';$('#repoToken').placeholder=state.repo.token?'Токен сохранён до закрытия вкладки':'github_pat_...'}
function clearRepoSession(){try{sessionStorage.removeItem(REPO_SESSION_KEY)}catch{}state.repo.token='';const token=$('#repoToken');if(token){token.value='';token.placeholder='github_pat_...'}}
async function api(path,opt={}){if(!state.repo.token)throw new Error('Сначала подключите GitHub.');const r=await fetch(`${API}/repos/${encodeURIComponent(state.repo.owner)}/${encodeURIComponent(state.repo.repo)}${path}`,{...opt,credentials:'omit',referrerPolicy:'no-referrer',headers:{'Accept':'application/vnd.github+json','Authorization':`Bearer ${state.repo.token}`,'X-GitHub-Api-Version':API_VERSION,'Content-Type':'application/json',...(opt.headers||{})},body:opt.body&&typeof opt.body!=='string'?JSON.stringify(opt.body):opt.body});if(!r.ok){let msg=`GitHub: ${r.status}`;try{const j=await r.json();msg=j.message||msg}catch{}throw new Error(msg)}return r.status===204?null:r.json()}
function decode64(s){const bin=atob((s||'').replace(/\n/g,'')),arr=Uint8Array.from(bin,c=>c.charCodeAt(0));return new TextDecoder().decode(arr)}
async function getRepoFile(path){path=repoSitePath(path);const j=await api('/contents/'+path.split('/').map(encodeURIComponent).join('/')+'?ref='+encodeURIComponent(state.repo.branch));return {content:decode64(j.content),sha:j.sha}}
async function commitChanges(changes,message){const branch=state.repo.branch;const ref=await api('/git/ref/heads/'+encodeURIComponent(branch));const head=ref.object.sha;const c=await api('/git/commits/'+head);const tree=changes.map(ch=>{const path=repoSitePath(ch.path);return ch.delete?{path,mode:'100644',type:'blob',sha:null}:{path,mode:'100644',type:'blob',content:ch.content}});const nt=await api('/git/trees',{method:'POST',body:{base_tree:c.tree.sha,tree}});const nc=await api('/git/commits',{method:'POST',body:{message,tree:nt.sha,parents:[head]}});await api('/git/refs/heads/'+encodeURIComponent(branch),{method:'PATCH',body:{sha:nc.sha,force:false}});return nc.sha}
async function fetchJsonRepo(path,fallback){try{return JSON.parse((await getRepoFile(path)).content)}catch(e){if(fallback)return fetch(BASE+path+'?v='+Date.now(),{cache:'no-store'}).then(r=>r.json());throw e}}
async function loadData(fromRepo=!!state.repo.token){const loader=fromRepo?(p=>fetchJsonRepo(p,true)):(p=>fetch(BASE+p+'?v='+Date.now(),{cache:'no-store'}).then(r=>r.json()));const [cfg,a,s,n]=await Promise.all([loader('content/cms-config.json'),loader('content/articles.json'),loader('content/sections.json'),loader('content/navigation.json')]);state.cfg=cfg;state.articles=a.articles||[];state.sections=s.sections||[];state.nav=n;const removed=pruneOrphanAutoSectionNav();renderAll();if(removed)notice(`Найдено и скрыто устаревших пунктов меню: ${removed}. Откройте «Левое меню» и нажмите «Сохранить меню», чтобы удалить их из репозитория.`)}
function renderAll(){renderArticles();renderSections();renderMenu();$('#articleCount').textContent=state.articles.length;$('#sectionCount').textContent=state.sections.length;const sel=$('#articleSectionFilter');const cur=sel.value;sel.innerHTML='<option value="">Все разделы</option>'+[...new Set(state.articles.map(a=>a.section).filter(Boolean))].sort().map(x=>`<option>${esc(x)}</option>`).join('');sel.value=cur}
function renderArticles(){const q=($('#articleSearch').value||'').toLowerCase(),sec=$('#articleSectionFilter').value;const list=state.articles.filter(a=>(!q||[a.title,a.description,a.section,a.url].join(' ').toLowerCase().includes(q))&&(!sec||a.section===sec));$('#articleList').innerHTML=list.length?list.map(a=>`<article class="content-row"><div><h3>${esc(a.title)}</h3><p>${esc(a.description||a.lead||'')}</p><div class="meta"><span class="badge">${esc(a.section||'Материалы')}</span><span class="badge">${a.type==='source'?'Источник':'Статья'}</span><span class="badge">${esc(a.url)}</span></div></div><div class="row-actions"><button class="ghost" data-edit-article="${esc(a.id)}">Редактировать</button><a class="ghost" href="${esc(safeInternalHref(a.url))}" target="_blank" rel="noopener noreferrer">↗</a></div></article>`).join(''):'<div class="empty">Ничего не найдено.</div>'}
function statNum(v){return new Intl.NumberFormat('ru-RU').format(Number(v)||0)}
function parseDetail(value){try{return JSON.parse(value||'{}')}catch{return {}}}
function statsEventCount(name){const row=(state.stats?.summary||[]).find(x=>x.event===name);return Number(row?.count||0)}
function articleTitle(path){const all=[...state.articles,...state.sections];const item=all.find(x=>safeInternalHref(x.url,'')===path);return item?.title||path}
function fmtDateTime(value){
 const d=new Date(value);if(Number.isNaN(d.getTime()))return '—';
 return new Intl.DateTimeFormat('ru-RU',{day:'2-digit',month:'2-digit',year:'2-digit',hour:'2-digit',minute:'2-digit'}).format(d);
}
function visitorShort(id){return '#'+String(id||'').slice(0,10)}
function actionLabel(event,detail){
 const d=parseDetail(detail);
 const map={page_view:'Просмотр страницы',read_depth:`Дочитал до ${Number(d.percent)||0}%`,bookmark:d.state==='saved'?'Добавил в избранное':'Убрал из избранного',affiliate_cta_click:'Переход в партнёрку',search:d.query?`Поиск: ${d.query}`:'Поиск по сайту',source_wizard_open:'Открыл подбор источника',source_wizard_answer:d.answer?`Ответ в подборе: ${d.answer}`:'Ответ в подборе',source_wizard_result_open:'Открыл результат подбора',diagnostic_problem:'Выбрал проблему диагностики',diagnostic_answer:'Ответил в диагностике',tool_action:d.tool?`Инструмент: ${d.tool}`:'Действие с инструментом',navigation:d.label?`Переход: ${d.label}`:'Переход по сайту',feedback:d.vote==='up'?'Поставил 👍':d.vote==='down'?'Поставил 👎':'Изменил оценку',article_reached_end:'Дошёл до конца статьи',audience_mode_change:'Сменил режим сайта',entry_mode:'Выбрал режим входа',first_meaningful_action:'Первое полезное действие'};
 return map[event]||event||'Действие';
}
function renderStats(){
 const data=state.stats;if(!data)return;
 const views=statsEventCount('page_view'),read90=statsEventCount('read_depth')?((data.reads90||[]).reduce((s,x)=>s+Number(x.count||0),0)):0;
 const bookmarkAdds=(data.bookmarks||[]).filter(x=>parseDetail(x.detail).state==='saved').reduce((s,x)=>s+Number(x.count||0),0);
 const affiliate=statsEventCount('affiliate_cta_click');
 const totalUp=(data.ratings||[]).reduce((s,x)=>s+Number(x.up||0),0),totalDown=(data.ratings||[]).reduce((s,x)=>s+Number(x.down||0),0);
 const ov=data.visitorOverview||{};
 const unique=Number(ov.unique_visitors||0),sessions=Number(ov.sessions||0),trackedPages=Number(ov.page_views||0);
 const pagesPerSession=sessions?Math.round(trackedPages/sessions*10)/10:0;
 $('#statsCards').innerHTML=[
   ['Просмотры',views,'за выбранный период'],
   ['Уникальные посетители',unique,'анонимных браузеров'],
   ['Новые посетители',Number(ov.new_visitors||0),'первый визит в периоде'],
   ['Повторные посетители',Number(ov.returning_visitors||0),'имеют 2+ сессии'],
   ['Сессии',sessions,'30 минут бездействия = новая'],
   ['Страниц за сессию',pagesPerSession,'по отслеживаемым сессиям'],
   ['Дочитали до 90%',read90,'срабатываний'],
   ['Добавили в закладки',bookmarkAdds,'добавлений'],
   ['Переходы в партнёрку',affiliate,'кликов'],
   ['Оценки статей',totalUp+totalDown,`👍 ${statNum(totalUp)} · 👎 ${statNum(totalDown)}`]
 ].map(x=>`<article class="stats-card"><span>${esc(x[0])}</span><b>${typeof x[1]==='number'&&!Number.isInteger(x[1])?String(x[1]).replace('.',','):statNum(x[1])}</b><small>${esc(x[2])}</small></article>`).join('');
 const readMap=new Map((data.reads90||[]).map(x=>[x.path,Number(x.count||0)]));
 const ratingMap=new Map((data.ratings||[]).map(x=>[x.path,x]));
 const pages=(data.topPages||[]).filter(x=>!x.path.startsWith('/admin/')).slice(0,50);
 $('#statsArticles').innerHTML=pages.length?pages.map(x=>{const r=ratingMap.get(x.path)||{};return `<tr><td><a href="${esc(safeInternalHref(x.path))}" target="_blank" rel="noopener noreferrer">${esc(articleTitle(x.path))}</a><small>${esc(x.path)}</small></td><td>${statNum(x.views)}</td><td>${statNum(readMap.get(x.path)||0)}</td><td>${statNum(r.up||0)}</td><td>${statNum(r.down||0)}</td></tr>`}).join(''):'<tr><td colspan="5">Пока нет данных.</td></tr>';
 const searches=(data.searches||[]).map(x=>({...parseDetail(x.detail),count:Number(x.count||0)})).filter(x=>x.query).slice(0,30);
 $('#statsSearches').innerHTML=searches.length?searches.map(x=>`<div class="stats-list-row"><span>${esc(x.query)}</span><b>${statNum(x.count)}</b></div>`).join(''):'<div class="stats-list-empty">Поисковых запросов пока нет.</div>';
 const visitorMap=new Map((data.visitors||[]).map(x=>[x.day,Number(x.unique_browsers||0)]));
 $('#statsDaily').innerHTML=(data.daily||[]).length?(data.daily||[]).slice().reverse().map(x=>`<tr><td>${esc(x.day)}</td><td>${statNum(x.views)}</td><td>${statNum(visitorMap.get(x.day)||0)}</td></tr>`).join(''):'<tr><td colspan="3">Пока нет данных.</td></tr>';
 const lastMap=new Map((data.lastVisitorActions||[]).map(x=>[x.visitor_hash,x]));
 const people=data.visitorSummaries||[];
 $('#statsVisitors').innerHTML=people.length?people.map(v=>{const last=lastMap.get(v.visitor_hash)||{};const repeat=Number(v.session_count||0)>1;return `<tr><td><b class="visitor-id">${esc(visitorShort(v.visitor_hash))}</b>${repeat?'<small class="visitor-repeat">Повторный</small>':'<small>Новый</small>'}</td><td>${esc(fmtDateTime(v.first_seen))}</td><td>${esc(fmtDateTime(v.period_last_seen||v.last_seen))}<small>${esc(actionLabel(last.event,last.detail))}</small></td><td>${statNum(v.period_sessions||0)}<small>всего ${statNum(v.session_count||0)}</small></td><td>${statNum(v.period_page_views||0)}</td><td>${statNum(v.period_events||0)}</td><td><button class="ghost visitor-history-btn" type="button" data-visitor-id="${esc(v.visitor_hash)}">История</button></td></tr>`}).join(''):'<tr><td colspan="7">Новая детализация начнёт появляться после обновления сайта и согласия посетителей на статистику.</td></tr>';
 $('#statsEmpty').hidden=true;$('#statsView').hidden=false;
}
async function loadVisitor(id){
 const days=Math.max(1,Math.min(365,Number($('#statsDays').value)||30));
 const r=await fetch(`/api/stats/visitor?id=${encodeURIComponent(id)}&days=${days}`,{cache:'no-store',credentials:'same-origin',headers:{'Accept':'application/json'}});
 let j={};try{j=await r.json()}catch{}
 if(!r.ok){if(r.status===401){location.assign('/admin/');throw new Error('Сессия администратора истекла.');}throw new Error('Не удалось загрузить историю посетителя: '+r.status)}
 const v=j.visitor||{};
 $('#visitorDialogTitle').textContent=`Посетитель ${visitorShort(v.visitor_hash)}`;
 $('#visitorDialogSummary').innerHTML=[['Первый визит',fmtDateTime(v.first_seen)],['Последний визит',fmtDateTime(v.last_seen)],['Сессии',statNum(v.session_count)],['Страницы',statNum(v.page_views)],['Действия',statNum(v.event_count)]].map(x=>`<div><span>${esc(x[0])}</span><b>${esc(x[1])}</b></div>`).join('');
 const sessions=j.sessions||[];
 $('#visitorSessions').innerHTML=sessions.length?sessions.map((s,i)=>`<article><div><b>Сессия ${sessions.length-i}</b><span>${esc(fmtDateTime(s.started_at))} → ${esc(fmtDateTime(s.last_seen))}</span></div><small>${statNum(s.page_views)} стр. · ${statNum(s.event_count)} действий · ${esc(s.entry_path)} → ${esc(s.exit_path)}</small></article>`).join(''):'<div class="stats-list-empty">Сессий за выбранный период нет.</div>';
 const events=j.events||[];
 $('#visitorEvents').innerHTML=events.length?events.map(e=>`<article><time>${esc(fmtDateTime(e.occurred_at))}</time><div><b>${esc(actionLabel(e.event,e.detail))}</b><a href="${esc(safeInternalHref(e.path))}" target="_blank" rel="noopener noreferrer">${esc(articleTitle(e.path))}</a><small>${esc(e.path)}</small></div></article>`).join(''):'<div class="stats-list-empty">Действий за выбранный период нет.</div>';
 $('#visitorDialog').showModal();
}
async function loadStats(){
 const days=Math.max(1,Math.min(365,Number($('#statsDays').value)||30));
 $('#statsEmpty').hidden=false;$('#statsEmpty').textContent='Загружаю статистику…';$('#statsView').hidden=true;
 const r=await fetch(`/api/stats?days=${days}`,{cache:'no-store',credentials:'same-origin',headers:{'Accept':'application/json'}});
 let j={};try{j=await r.json()}catch{}
 if(!r.ok){
   if(j.error==='d1_binding_missing')throw new Error('В Cloudflare не подключена D1-база с именем DB.');
   if(r.status===401){location.assign('/admin/');throw new Error('Сессия администратора истекла. Войдите снова.');}
   if(r.status===403)throw new Error('Запрос статистики отклонён защитой Origin.');
   throw new Error('Не удалось загрузить статистику: '+r.status);
 }
 state.stats=j;renderStats();
}

async function resetStats(){
 const button=$('#confirmResetStats');
 const dialog=$('#resetStatsDialog');
 const oldText=button.textContent;
 button.disabled=true;button.textContent='Сбрасываю…';
 try{
   const r=await fetch('/api/stats/reset',{
     method:'POST',
     cache:'no-store',
     credentials:'same-origin',
     headers:{'Accept':'application/json','Content-Type':'application/json'},
     body:JSON.stringify({confirm:'RESET_STATS'})
   });
   let j={};try{j=await r.json()}catch{}
   if(!r.ok){
     if(j.error==='d1_binding_missing')throw new Error('В Cloudflare не подключена D1-база с именем DB.');
     if(r.status===401){location.assign('/admin/');throw new Error('Сессия администратора истекла. Войдите снова.');}
     if(r.status===403)throw new Error('Сброс статистики отклонён защитой Origin.');
     if(r.status===400)throw new Error('Сервер не подтвердил запрос на сброс статистики.');
     throw new Error('Не удалось сбросить статистику: '+r.status);
   }
   state.stats=null;
   dialog.close();
   notice('Статистика полностью сброшена. Новые данные будут собираться с нуля.');
   await loadStats();
 }finally{
   button.disabled=false;button.textContent=oldText;
 }
}

function renderSections(){const list=state.sections;$('#sectionList').innerHTML=list.length?list.map(s=>`<article class="content-row"><div><h3>${esc(s.title)}</h3><p>${esc(s.description||'')}</p><div class="meta"><span class="badge">${esc(s.url)}</span>${s.system?'<span class="badge">Системный</span>':''}</div></div><div class="row-actions"><button class="ghost" data-edit-section="${esc(s.id)}">Редактировать</button><a class="ghost" href="${esc(safeInternalHref(s.url))}" target="_blank" rel="noopener noreferrer">↗</a></div></article>`).join(''):'<div class="empty">Разделов нет.</div>'}
function renderMenu(){const host=$('#menuEditor');host.innerHTML=(state.nav.groups||[]).map((g,gi)=>`<section class="menu-group" data-group="${gi}"><div class="menu-group-head"><input maxlength="80" value="${esc(g.title)}" data-group-title><div class="small-actions"><button data-up-group title="Выше">↑</button><button data-down-group title="Ниже">↓</button><button data-del-group title="Удалить">×</button></div></div><div class="menu-items">${(g.items||[]).map((it,ii)=>menuItemHtml(it,ii)).join('')}</div><button class="ghost menu-add" data-add-item>+ Пункт</button></section>`).join('')}
function menuItemHtml(it,ii){return `<div class="menu-item" data-item="${ii}"><input maxlength="3" value="${esc(it.icon||'•')}" data-icon title="Значок"><input maxlength="80" value="${esc(it.title||'')}" data-title placeholder="Название"><input maxlength="220" value="${esc(it.href||'')}" data-href placeholder="/..."><div class="small-actions"><button data-up-item>↑</button><button data-down-item>↓</button><button data-del-item>×</button></div></div>`}
function syncMenuFromDom(){const groups=[];$$('.menu-group').forEach((g,gi)=>{const items=[];$$('.menu-item',g).forEach((it,ii)=>{const title=$('[data-title]',it).value.trim();const raw=$('[data-href]',it).value.trim();const href=safeInternalHref(raw,'');if(!href)throw new Error('Пункт меню «'+(title||'Без названия')+'» должен вести только на внутреннюю страницу TrafficLab.');items.push({id:slugify(title)+'-'+ii,title,href,icon:$('[data-icon]',it).value.trim()||'•'})});groups.push({id:'group-'+(gi+1),title:$('[data-group-title]',g).value.trim()||'Раздел',items})});state.nav={version:1,groups}}
const CORE_NAV_IDS=new Set(['start','traffic','compare','practice','diagnostics','analytics','tools','services','library','basics','glossary','notes','history','saved','about','help','privacy','terms','path','economics']);
function normMenuHref(value){const h=safeInternalHref(value,'');if(!h)return '';try{let p=new URL(h,location.origin).pathname;return p.endsWith('/')?p:p+'/'}catch{return ''}}
function sectionSlugFromHref(value){const p=normMenuHref(value);const parts=p.split('/').filter(Boolean);return parts.length===1?decodeURIComponent(parts[0]):''}
function findSectionNavItem(section){if(!section)return null;const id=String(section.id||''),url=normMenuHref(section.url);for(let gi=0;gi<(state.nav.groups||[]).length;gi++){const items=state.nav.groups[gi].items||[];for(let ii=0;ii<items.length;ii++){const it=items[ii];if((id&&String(it.id||'')===id)||(url&&normMenuHref(it.href)===url))return{gi,ii,item:it}}}return null}
function removeSectionNavEntries(section){let changed=false;const id=String(section?.id||''),url=normMenuHref(section?.url);(state.nav.groups||[]).forEach(g=>{const before=(g.items||[]).length;g.items=(g.items||[]).filter(it=>!((id&&String(it.id||'')===id)||(url&&normMenuHref(it.href)===url)));if(g.items.length!==before)changed=true});return changed}
function upsertSectionNavEntry(section,show,groupIndex,icon){let changed=removeSectionNavEntries(section);if(!show)return changed;const gi=Math.max(0,Math.min(Number(groupIndex)||0,Math.max(0,(state.nav.groups||[]).length-1)));state.nav.groups[gi]??={id:'group-'+(gi+1),title:'Раздел',items:[]};state.nav.groups[gi].items.push({id:section.id,title:section.menuTitle||section.title,href:section.url,icon:icon||'•'});return true}
function pruneOrphanAutoSectionNav(){const validIds=new Set((state.sections||[]).map(s=>String(s.id||'')));let removed=0;(state.nav.groups||[]).forEach(g=>{g.items=(g.items||[]).filter(it=>{const id=String(it.id||'');if(CORE_NAV_IDS.has(id)||validIds.has(id))return true;const slug=sectionSlugFromHref(it.href);const auto=!!slug&&slug===id;if(auto){removed++;return false}return true})});return removed}
function ensureUniquePath(path,originalPath=''){const taken=[...(state.sections||[]).map(x=>x.path),...(state.articles||[]).map(x=>x.path)].filter(Boolean);if(taken.some(p=>p===path&&p!==originalPath))throw new Error('Такой адрес уже используется другим материалом. Измените Slug.');const root=String(path||'').split('/')[0];if(['admin','assets','content','.well-known','go','notes','history','saved','privacy','terms'].includes(root)&&path!==originalPath)throw new Error('Этот Slug зарезервирован системой. Выберите другой.');}
function fieldsArticle(a,isNew){const slugValue=isNew?'':((a.path||'').split('/').slice(-2,-1)[0]||'');return `<div class="form-grid"><label>Заголовок<input maxlength="140" name="title" value="${esc(a.title||'')}"></label><label>Slug<input maxlength="80" name="slug" value="${esc(slugValue)}" placeholder="Заполнится из заголовка"></label><label>Раздел<input maxlength="80" name="section" value="${esc(a.section||'Материалы')}"></label><label>Метка<input maxlength="50" name="label" value="${esc(a.label||'Статья')}"></label><label class="full">Описание для поиска и SEO<textarea maxlength="320" name="description" rows="2">${esc(a.description||'')}</textarea></label><label class="full">Лид под заголовком<textarea maxlength="500" name="lead" rows="2">${esc(a.lead||a.description||'')}</textarea></label><label>Уровень<select name="level"><option value="beginner" ${a.level!=='advanced'?'selected':''}>С нуля</option><option value="advanced" ${a.level==='advanced'?'selected':''}>После базы</option></select></label><label>Время чтения<input maxlength="30" name="readTime" value="${esc(a.readTime||'5 мин')}"></label><label>Дата<input maxlength="30" name="date" value="${esc(a.date||new Date().toLocaleDateString('ru-RU'))}"></label><label>Показывать в библиотеке<select name="libraryVisible"><option value="true" ${a.libraryVisible!==false?'selected':''}>Да</option><option value="false" ${a.libraryVisible===false?'selected':''}>Нет</option></select></label><label class="full">Ключевые слова<input maxlength="500" name="aliases" value="${esc(a.aliases||'')}"></label></div>`}
function fieldsSection(s){const found=findSectionNavItem(s),inMenu=!!found,slugValue=s.system?(s.path||'').split('/')[0]:((s.path&&s.path!=='new/index.html')?s.path.split('/')[0]:'');const groupIndex=found?found.gi:0;return `<div class="form-grid"><label>Название<input maxlength="140" name="title" value="${esc(s.title||'')}"></label><label>Slug<input maxlength="80" name="slug" value="${esc(slugValue)}" placeholder="Заполнится из названия" ${s.system?'readonly':''}></label><label class="full">Описание<textarea maxlength="320" name="description" rows="2">${esc(s.description||'')}</textarea></label><label>Пункт меню<input maxlength="80" name="menuTitle" value="${esc(s.menuTitle||s.title||'')}"></label><label>Значок<input name="icon" maxlength="3" value="${esc(found?.item?.icon||s.icon||'•')}"></label><label>Добавить в меню<select name="showInMenu"><option value="true" ${inMenu?'selected':''}>Да</option><option value="false" ${!inMenu?'selected':''}>Нет</option></select></label><label>Группа меню<select name="menuGroup">${(state.nav.groups||[]).map((g,i)=>`<option value="${i}" ${i===groupIndex?'selected':''}>${esc(g.title)}</option>`).join('')}</select></label></div>`}
