function getBody(){const raw=state.mode==='visual'?$('#visualEditor').innerHTML.trim():$('#htmlEditor').value.trim();if(new TextEncoder().encode(raw).byteLength>250000)throw new Error('Текст материала слишком большой. Максимальный размер HTML - 250 КБ.');const safe=sanitizeEditorBody(raw);if(safe.changed)notice('Опасные элементы или атрибуты HTML удалены перед сохранением.');return safe.html}
function replaceBetween(text,start,end,body){const a=text.indexOf(start),b=text.indexOf(end);if(a<0||b<a)throw new Error('В файле не найдены служебные метки редактора.');return text.slice(0,a+start.length)+'\n'+body+'\n'+text.slice(b)}
