function sitemapXml(){const base=state.cfg?.canonicalBase||'https://traff-lab.com/';const today=new Date().toISOString().slice(0,10);const rows=new Map([[base,today],[base+'economics/',today],[base+'traffic/compare/',today]]);state.sections.filter(s=>s.id!=='help').forEach(s=>rows.set(base+s.path.replace(/index\.html$/,''),today));state.articles.forEach(a=>rows.set(base+a.path.replace(/index\.html$/,''),isoDate(a.date)));const escXml=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&apos;');return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${[...rows.entries()].sort((a,b)=>a[0].localeCompare(b[0])).map(([u,d])=>`  <url><loc>${escXml(u)}</loc><lastmod>${d}</lastmod></url>`).join('\n')}\n</urlset>\n`}
