async function init(){bind();loadSession();if(state.repo.token){try{const j=await api('');$('#connectionState').textContent=`${j.full_name} · ${state.repo.branch}`;$('#connectionState').className='state online';await loadData(true);return}catch(e){$('#connectionState').textContent='Подключение требует проверки';$('#connectionState').className='state offline';notice('Сохранённое подключение GitHub не удалось проверить. При необходимости откройте «Подключение».','error')}}await loadData(false)}
